<script>
// --- prototype-only mock of "automatic detail fetching" ---
const MOCK = {
  "figma.com": {title:"Figma: The Collaborative Interface Design Tool", desc:"Design, prototype, and gather feedback all in one place."},
  "developer.mozilla.org": {title:"MDN Web Docs", desc:"Resources for developers, by developers."},
  "nytimes.com": {title:"The New York Times — Breaking News, US & World", desc:"Live news, investigations, opinion, photos and video."},
  "github.com": {title:"GitHub · Build and ship software", desc:"The complete developer platform to build, scale, and deliver software."},
  "stripe.com": {title:"Stripe | Payment Processing Platform", desc:"Online payment processing for internet businesses."}
};
function domainOf(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch { return ""; } }
function lookup(u){
  const d = domainOf(u);
  if (MOCK[d]) return MOCK[d];
  if (!d) return null;
  const name = d.split(".")[0];
  return { title: name.charAt(0).toUpperCase()+name.slice(1) + " — " + d, desc: "Saved from " + d };
}

let pending = null;      // {url, title, desc, tags:[]}
let items = [];

const $ = id => document.getElementById(id);
function toast(msg){ const t=$("toast"); t.textContent=msg; t.classList.add("show"); setTimeout(()=>t.classList.remove("show"),1600); }

$("fetchBtn").onclick = doFetch;
$("url").addEventListener("keydown", e => { if(e.key==="Enter") doFetch(); });

function doFetch(){
  const u = $("url").value.trim();
  if(!u){ toast("Paste a link first"); return; }
  const meta = lookup(u);
  if(!meta){ toast("That doesn't look like a valid link"); return; }
  pending = { url:u, title:meta.title, desc:meta.desc, tags:[] };
  $("pvFav").textContent = domainOf(u).charAt(0).toUpperCase() || "?";
  $("pvTitle").textContent = meta.title;
  $("pvDesc").textContent = meta.desc;
  $("titleEdit").value = meta.title;
  $("note").value = "";
  $("tagInput").value = "";
  renderTags();
  $("preview").style.display = "block";
}

$("tagInput").addEventListener("keydown", e => {
  if(e.key==="Enter"){
    e.preventDefault();
    const v = e.target.value.trim().replace(/,$/,"");
    if(v && !pending.tags.includes(v)){ pending.tags.push(v); renderTags(); }
    e.target.value="";
  }
});
function renderTags(){
  const el = $("tagList"); el.innerHTML="";
  pending.tags.forEach((t,i)=>{
    const s=document.createElement("span"); s.className="tag";
    s.innerHTML = t+' <button title="remove">×</button>';
    s.querySelector("button").onclick = ()=>{ pending.tags.splice(i,1); renderTags(); };
    el.appendChild(s);
  });
}

$("cancelBtn").onclick = ()=>{ pending=null; $("preview").style.display="none"; $("url").value=""; };

$("saveBtn").onclick = ()=>{
  if(!pending) return;
  pending.title = $("titleEdit").value.trim() || pending.title;
  pending.note = $("note").value.trim();
  items.unshift({...pending, id:Date.now()});
  pending=null;
  $("preview").style.display="none";
  $("url").value="";
  renderItems();
  toast("Saved");
};

function renderItems(){
  const el=$("items");
  if(items.length===0){ el.innerHTML='<div class="empty">No bookmarks yet — paste a link above to save your first one.</div>'; return; }
  el.innerHTML="";
  items.forEach(it=>{
    const d=domainOf(it.url);
    const div=document.createElement("div"); div.className="item";
    div.innerHTML =
      '<div class="fav">'+(d.charAt(0).toUpperCase()||"?")+'</div>'+
      '<div><div class="t">'+esc(it.title)+'</div>'+
      '<div class="u">'+esc(it.url)+'</div>'+
      (it.note?'<div class="note">'+esc(it.note)+'</div>':'')+
      (it.tags.length?'<div class="tags">'+it.tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div>':'')+
      '</div>';
    el.appendChild(div);
  });
}
function esc(s){ return s.replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

renderItems();
document.body.setAttribute("data-harness-ready","true");
</script>
</body>
